# Create YOUR defect issues on GitHub (PowerShell version, no bash needed).
# Usage, each member signed in as themselves:
#   gh auth login
#   .\scripts\create_issues.ps1 -Member M1   # Khalil
#   .\scripts\create_issues.ps1 -Member M2   # Monir
#   .\scripts\create_issues.ps1 -Member M3   # Abdulaziz
param([Parameter(Mandatory=$true)][ValidateSet("M1","M2","M3")][string]$Member)
$ErrorActionPreference = "Stop"
Set-Location (Join-Path $PSScriptRoot "..")
$repo = if ($env:REPO) { $env:REPO } else { gh repo view --json nameWithOwner -q .nameWithOwner }
Write-Host "Creating $Member issues in $repo as $(gh api user -q .login)"
if ($Member -eq "M1") { gh issue create --repo $repo --title "[D01] Match score is cached per posting and shared across students" --body-file "docs/issues/D01-match-score-is-cached-per-posting-and-shared-acros.md" --label "integration,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M1") { gh issue create --repo $repo --title "[D02] Filling a posting does not reject its remaining active applications" --body-file "docs/issues/D02-filling-a-posting-does-not-reject-its-remaining-ac.md" --label "state,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M1") { gh issue create --repo $repo --title "[D03] Two students can accept offers for the last seat at the same moment" --body-file "docs/issues/D03-two-students-can-accept-offers-for-the-last-seat-a.md" --label "state,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M1") { gh issue create --repo $repo --title "[D04] A suspended company's applications are not frozen" --body-file "docs/issues/D04-a-suspended-company-s-applications-are-not-frozen.md" --label "functional,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M3") { gh issue create --repo $repo --title "[D05] Any authenticated user can view any application (broken access control)" --body-file "docs/issues/D05-any-authenticated-user-can-view-any-application-br.md" --label "security,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M3") { gh issue create --repo $repo --title "[D48] Any recruiter can download any student's CV and transcript" --body-file "docs/issues/D48-any-recruiter-can-download-any-student-s-cv-and-tr.md" --label "security,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M3") { gh issue create --repo $repo --title "[D06] API key and SMTP password are written to the log and shown in plaintext" --body-file "docs/issues/D06-api-key-and-smtp-password-are-written-to-the-log-a.md" --label "security,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M3") { gh issue create --repo $repo --title "[D07] Stored XSS via company name on the postings list" --body-file "docs/issues/D07-stored-xss-via-company-name-on-the-postings-list.md" --label "security,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M3") { gh issue create --repo $repo --title "[D08] Student name, number and GPA are sent to the AI provider" --body-file "docs/issues/D08-student-name-number-and-gpa-are-sent-to-the-ai-pro.md" --label "security,severity:critical,priority:p1" --assignee "@me" }
if ($Member -eq "M1") { gh issue create --repo $repo --title "[D47] An ACCEPTED application can be withdrawn via a direct POST" --body-file "docs/issues/D47-an-accepted-application-can-be-withdrawn-via-a-dir.md" --label "state,severity:critical,priority:p1" --assignee "@me" }
